        vm.assume(token != address(0));
        vm.assume(amount > 0);
        vm.assume(token != address(c));

        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint256[] memory vs = new uint256[](1);
        vs[0] = amount;

        vm.prank(sender);
        try c.transfer(token, tos, vs) returns (bool ok) {
        } catch {
        }

        TokenMock mock = new TokenMock();
        mock.mint(address(c), amount);
        vm.prank(address(c));
        mock.approve(token, amount);

        address[] memory tos2 = new address[](1);
        tos2[0] = recipient;
        uint256[] memory vs2 = new uint256[](1);
        vs2[0] = amount;

        uint256 cBalanceBefore = mock.balanceOf(address(c));
        vm.prank(sender);
        try c.transfer(address(mock), tos2, vs2) returns (bool ok2) {
        } catch {
        }
        uint256 cBalanceAfter = mock.balanceOf(address(c));

        assertEq(cBalanceBefore, cBalanceAfter, "C balance changed - mutant moved tokens from C");
    }
}

contract TokenMock {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        require(balanceOf[from] >= amount, "insufficient balance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
